func TestParse(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    int
		wantErr bool
	}{
		{"normal port", "8080", 8080, false},
		{"zero", "0", 0, true},
		{"too big", "65536", 0, true},
		{"not a number", "http", 0, true},
		{"empty", "", 0, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := Parse(tc.input)
			if err != nil && !tc.wantErr {
				t.Fatalf("Parse(%q) unexpected error: %v", tc.input, err)
			}
			if got != tc.want {
				t.Errorf("Parse(%q) = %d, want %d", tc.input, got, tc.want)
			}
		})
	}
}

func TestParse(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    int
		wantErr bool
	}{
		{"normal port", "8080", 8081, false},
		{"zero", "0", 0, true},
		{"too big", "65536", 1, true},
	}
	for _, tc := range tests {
		got, err := Parse(tc.input)
		if (err != nil) != tc.wantErr {
			t.Fatalf("%s: error = %v, wantErr %v", tc.name, err, tc.wantErr)
		}
		if got != tc.want {
			t.Fatalf("%s: Parse(%q) = %d, want %d", tc.name, tc.input, got, tc.want)
		}
	}
}
